import sys


class AddToCart:
    def addItem(self, item):
        raise NotImplementedError


class Payment:
    def makePayment(self):
        raise NotImplementedError


class ShoppingCart(AddToCart, Payment):
    def __init__(self):
        self.items = []

    def addItem(self, item):
        self.items.append(item)
        print(f"Item added: {item}")

    def makePayment(self):
        print(f"Payment successful for {len(self.items)} items.")


def main():
    cart = ShoppingCart()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if line == "pay":
            cart.makePayment()
            break
        if line.startswith("add"):
            item = line[3:].strip()
            cart.addItem(item)


if __name__ == "__main__":
    main()
